--- a/src/language-js/print/typescript.js
+++ b/src/language-js/print/typescript.js
@@ -457,8 +457,14 @@ function printTypescript(path, options, print) {
       if (node.isExport) {
         parts.push("export ");
       }
+
+      parts.push("import ");
+
+      if (node.importKind && node.importKind !== "value") {
+        parts.push(node.importKind, " ");
+      }
+
       parts.push(
-        "import ",
         path.call(print, "id"),
         " = ",
